xql_query:
// ============================================================
// Rule: TNB_Public Virtual Machine Created
// Vendor: Tenable
// Objective:
// Detect activity associated with TNB_Public Virtual Machine Created.
// Severity: SEV_050_CRITICAL
// Category: OTHER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1578 - Modify Cloud Compute Infrastructure
// Technique: T1578.002 - Modify Cloud Compute Infrastructure: Create Cloud Instance

// Fonte de dados: logs brutos do Tenable
dataset = tenable_tenable_raw  

// Filtro para identificar apenas eventos com o título específico
// "Public Virtual Machine"
| filter (title = """Public Virtual Machine""")  

// Seleção dos campos mais relevantes para análise
| fields title,            // Título da detecção (descrição curta do achado)
         description,      // Detalhes adicionais do alerta
         accountName,      // Conta de nuvem associada ao recurso
         resourceOwner,    // Proprietário do recurso identificado
         sentBy,           // Origem do alerta ou mecanismo de detecção
         policyName,       // Política de conformidade ou segurança violada
         resources,        // Recursos impactados (ex.: IDs das VMs públicas)
         accountName,      // Conta associada (repetida, útil para correlação)
         link              // Link para detalhes completos no Tenable
